{"command": "create", "path": "/workspace/project/twitch-chat-reader/styles.css", "file_text": "* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    color: #333;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

header {
    text-align: center;
    margin-bottom: 30px;
    color: white;
}

header h1 {
    font-size: 2.5rem;
    margin-bottom: 10px;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

header p {
    font-size: 1.1rem;
    opacity: 0.9;
}

.controls {
    background: white;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.input-group {
    display: flex;
    gap: 10px;
    align-items: center;
    margin-bottom: 25px;
    flex-wrap: wrap;
}

.input-group label {
    font-weight: 600;
    min-width: 120px;
}

.input-group input[type="text"] {
    flex: 1;
    padding: 12px;
    border: 2px solid #e1e5e9;
    border-radius: 8px;
    font-size: 16px;
    min-width: 200px;
}

.input-group input[type="text"]:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

button {
    padding: 12px 20px;
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
}

button:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0,0,0,0.2);
}

#connect-btn {
    background: #28a745;
    color: white;
}

#connect-btn:hover {
    background: #218838;
}

#disconnect-btn {
    background: #dc3545;
    color: white;
}

#disconnect-btn:hover {
    background: #c82333;
}

#disconnect-btn:disabled {
    background: #6c757d;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
}

.settings {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
    margin-bottom: 25px;
}

.settings h3 {
    grid-column: 1 / -1;
    color: #667eea;
    border-bottom: 2px solid #e1e5e9;
    padding-bottom: 10px;
    margin-bottom: 15px;
}

.setting-group {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.setting-group label {
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 8px;
}

.setting-group input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

.setting-group select,
.setting-group input[type="text"] {
    padding: 8px;
    border: 2px solid #e1e5e9;
    border-radius: 6px;
    font-size: 14px;
}

.setting-group input[type="range"] {
    width: 100%;
}

.muted-users {
    border-top: 2px solid #e1e5e9;
    padding-top: 20px;
}

.muted-users h3 {
    color: #667eea;
    margin-bottom: 15px;
}

.muted-list {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 15px;
    min-height: 40px;
    padding: 10px;
    background: #f8f9fa;
    border-radius: 8px;
}

.muted-user {
    background: #dc3545;
    color: white;
    padding: 5px 10px;
    border-radius: 15px;
    font-size: 12px;
    display: flex;
    align-items: center;
    gap: 5px;
}

.muted-user .remove {
    cursor: pointer;
    font-weight: bold;
}

.mute-input {
    display: flex;
    gap: 10px;
}

.mute-input input {
    flex: 1;
    padding: 8px;
    border: 2px solid #e1e5e9;
    border-radius: 6px;
}

#mute-btn {
    background: #ffc107;
    color: #212529;
}

#mute-btn:hover {
    background: #e0a800;
}

.status {
    display: flex;
    gap: 20px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}

.status > div {
    padding: 15px 20px;
    border-radius: 10px;
    font-weight: 600;
    flex: 1;
    min-width: 200px;
    text-align: center;
}

.status-disconnected {
    background: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

.status-connected {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.current-speaking {
    background: #fff3cd;
    color: #856404;
    border: 1px solid #ffeaa7;
}

.chat-display,
.queue-display {
    background: white;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.chat-display h3,
.queue-display h3 {
    color: #667eea;
    margin-bottom: 15px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.messages,
.queue {
    max-height: 300px;
    overflow-y: auto;
    border: 2px solid #e1e5e9;
    border-radius: 8px;
    padding: 15px;
    margin-bottom: 15px;
    background: #f8f9fa;
}

.message {
    margin-bottom: 10px;
    padding: 8px;
    border-radius: 6px;
    background: white;
    border-left: 4px solid #667eea;
}

.message.event {
    border-left-color: #28a745;
    background: #f8fff9;
}

.message.filtered {
    border-left-color: #ffc107;
    background: #fffdf5;
}

.message-header {
    font-weight: 600;
    color: #667eea;
    font-size: 12px;
    margin-bottom: 4px;
}

.message-content {
    color: #333;
}

.queue-item {
    margin-bottom: 8px;
    padding: 8px;
    background: white;
    border-radius: 6px;
    border-left: 4px solid #17a2b8;
    font-size: 14px;
}

.queue-item.speaking {
    border-left-color: #28a745;
    background: #f8fff9;
}

#clear-chat,
#clear-queue,
#pause-speech,
#resume-speech {
    background: #6c757d;
    color: white;
    margin-right: 10px;
}

#clear-chat:hover,
#clear-queue:hover {
    background: #5a6268;
}

#pause-speech {
    background: #ffc107;
    color: #212529;
}

#pause-speech:hover {
    background: #e0a800;
}

#resume-speech {
    background: #28a745;
    color: white;
}

#resume-speech:hover {
    background: #218838;
}

@media (max-width: 768px) {
    .container {
        padding: 10px;
    }

    .input-group {
        flex-direction: column;
        align-items: stretch;
    }

    .input-group label {
        min-width: auto;
    }

    .settings {
        grid-template-columns: 1fr;
    }

    .status {
        flex-direction: column;
    }
}

/* Scrollbar styling */
.messages::-webkit-scrollbar,
.queue::-webkit-scrollbar {
    width: 8px;
}

.messages::-webkit-scrollbar-track,
.queue::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 4px;
}

.messages::-webkit-scrollbar-thumb,
.queue::-webkit-scrollbar-thumb {
    background: #c1c1c1;
    border-radius: 4px;
}

.messages::-webkit-scrollbar-thumb:hover,
.queue::-webkit-scrollbar-thumb:hover {
    background: #a8a8a8;
}"}

