processQueue() {
    if (this.speechQueue.length === 0 || this.isPaused) {
        this.isSpeaking = false;
        this.elements.currentSpeaking.textContent = '';
        return;
    }

    const text = this.speechQueue.shift();
    this.isSpeaking = true;
    this.elements.currentSpeaking.textContent = `Speaking: ${text.substring(0, 50)}...`;

    const utterance = new SpeechSynthesisUtterance(text);

    // Apply settings
    const voices = this.synth.getVoices();
    const selectedVoiceIndex = this.elements.voiceSelect.value;
    if (voices[selectedVoiceIndex]) {
        utterance.voice = voices[selectedVoiceIndex];
    }

    utterance.rate = parseFloat(this.elements.speechRate.value);
    utterance.volume = parseFloat(this.elements.speechVolume.value);

    utterance.onend = () => {
        this.isSpeaking = false;
        this.updateQueueDisplay();
        setTimeout(() => this.processQueue(), 100);
    };

    utterance.onerror = (event) => {
        console.error('Speech synthesis error:', event);
        this.isSpeaking = false;
        this.updateQueueDisplay();
        setTimeout(() => this.processQueue(), 100);
    };

    this.synth.speak(utterance);
    this.updateQueueDisplay();
}

